-- 2224 🏋️ Exercises from the book "marcelo-bielsa-attacking-tactics-and-sessions" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'marcelo-bielsa-attacking-tactics-and-sessions');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('DM drops back, position-specific passing pattern', 'passing_unopposed', 'unopposed', 'in_possession', 36, 36, 'Session for Tactical Situation 1: Practice 1', 'Bielsa (Leeds United)', 'Rehearse the defensive midfielder dropping deep to make a back three and the ball then travelling up the flank via the attacking midfielder, full back and winger to a finish.', '40 x 50 yard area or up to half a pitch, split into two halves each with a goal; 8 mannequins stand in for the opponents'' 2 forwards, 4 midfielders and 2 full backs. Each half has a centre back with balls, a DM, an attacking mid, full back and winger.', 'Centre back plays into the DM, who sets it back and drops deep (inside on one half, wide on the other) to receive again. The DM then feeds the attacking midfielder who has also dropped in as a second line player, on to the advanced full back, who crosses for the winger to score.', 'Unopposed; mannequins only. Left half uses chain-reaction movements, right half uses rotations.', NULL, 'Synchronised movement; DM chooses inside or wide drop; receive half-turned.', '2 groups, positional (CB, DM, AM, FB, winger), 2 players per advanced position to keep it flowing', 10, 16, '40 x 50 yards (or up to half a pitch, divided in half)', 45.7, 36.6, NULL, true, false, true, NULL, 10),
  ('Back three build-up functional pattern vs mannequins', 'combination', 'unopposed', 'in_possession', 37, 38, 'Session for Tactical Situation 1: Practice 2 (Progression)', 'Bielsa (Leeds United)', 'Whole team rehearses forming a back three with the DM and moving the ball to the side where it has more attacking players, finishing on goal.', 'Full area (half pitch) with one goal and about 10 mannequins as the opposing shape; centre backs start with balls, DM, two attacking mids, full backs, wingers in their positions.', 'Centre backs pass between themselves and to the full backs until the DM drops (wide in scenario A, between the centre backs in scenario B) to make a back three; the others shift with chain or rotation movements. The ball goes to one of the back three who steps forward and reads which side is overloaded, then plays to the full back, winger or dropping attacking midfielder there, who crosses, turns and shoots or combines to finish.', 'Unopposed; ball must go to the side with more attacking players.', 'Scenario A: DM drops into a wide slot. Scenario B: DM drops between the centre backs and the ball goes via the dropping attacking midfielder to the weak side. Other attacking patterns from later in the book can be added.', 'Read the situation (chain vs rotation); synchronised movement; high tempo; body shape half-turned to progress.', '9-10 outfield players', 9, 11, 'Half a pitch', NULL, NULL, NULL, true, false, true, NULL, 20),
  ('Back three build-up 9v8 game with mini goals', 'conditioned_game', 'opposed', 'in_possession', 39, 39, 'Session for Tactical Situation 1: Practice 3 (Progression)', 'Bielsa (Leeds United)', 'Create a 3v2 at the back by dropping the DM and break the pressure of two forwards, then attack on the side with the advantage.', 'About two thirds of a pitch with a full goal and GK at one end and 2 mini goals at the other; a low zone is marked at the whites'' end where the reds'' two forwards press.', 'Whites build from their two centre backs; the DM drops wide or between them to make a 3v2 in the low zone against the reds'' No.9 and No.10, the rest use chain or rotation movements. The back three find the free player, move forward and play towards the overloaded side to score in the big goal.', 'If the reds win the ball they counter to score in either mini goal.', 'Patterns shown later in the book can be added.', 'Find the free man in the back three; switch the attack to the side with more players.', '9v8 (+GK)', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 30),
  ('7v3 rondo finding the free middle player', 'rondo', 'overload', 'in_possession', 55, 55, 'Situation 2 Session: Practice 1', 'Bielsa (Leeds United)', 'Effective support positioning between defenders so the ball can be split through to a free central player and switched to the far side.', 'Rondo square with 5 white players on the outside, 2 whites inside acting as central midfielders and 3 red defenders inside.', 'Whites keep the ball; the two inside players hunt pockets between the reds to take a split pass, then move it on to an outside player on the opposite side, either with control and pass or a quick combination between the two inside players. Reds try to win it as often as they can in a set time (e.g. 2 minutes), then roles rotate.', 'Outside players 1 touch, inside players 2 touches. Whites score 1 point each time the ball goes through the middle and out to the other side.', NULL, 'Best with central midfielders inside; get out of defenders'' shadows; sit between opponents; receive half-turned with open body; play at high tempo.', '7v3', 10, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 40),
  ('Mannequin lane: direct split pass to free man', 'passing_unopposed', 'unopposed', 'in_possession', 56, 56, 'Situation 2 Session: Practice 2', 'Bielsa (Leeds United)', 'Getting free of markers between the lines using support-positioning principles and receiving a third-line through pass.', '30 x 40 yard area split in two halves, 7 players per half working at once; 5 mannequins per half and 2 mini goals at the far end of each half. Positions A, B, C, D.', 'D lofts a ball to A, who sets B dropping at an angle in front of a mannequin. As B receives, C finds a gap between the mannequins on the half-turn; B plays a through pass straight to C, who drives forward and finishes in a mini goal. Rotate A to B to C to D to A.', NULL, NULL, 'Make a triangle so the ball carrier has two options; step out of the mannequin''s shadow; position between lines and opponents; open body to receive; synchronised, quick movements.', '14 (7 per half)', 8, 14, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 50),
  ('Mannequin lane: through pass and set via link', 'passing_unopposed', 'unopposed', 'in_possession', 57, 57, 'Situation 2 Session: Practice 3', 'Bielsa (Leeds United)', 'Using a link player to set the ball back to the free man between the lines when the direct pass is not on.', 'Same halves, mannequins and mini goals as Practice 2 (30 x 40 yards, 7 per half).', 'Start as before from D''s lofted ball. C and D drop on opposite sides to form a triangle with B. B plays forward to D, who lays the ball back to C (through pass then set); C carries forward and scores in a mini goal. Rotate positions.', NULL, NULL, 'Triangle gives two passing options; move out of the mannequin''s shadow; position between lines and between opponents; receive with good body shape; synchronised rotation at high speed.', '14 (7 per half)', 8, 14, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 60),
  ('Mannequin lane: wall pass then split pass', 'passing_unopposed', 'unopposed', 'in_possession', 58, 58, 'Situation 2 Session: Practice 4', 'Bielsa (Leeds United)', 'Creating a better passing angle with a short first-line return pass before the through ball to the free player.', 'Same halves, mannequins and mini goals as Practice 2 (30 x 40 yards).', 'After passing to B, A runs forward to offer a return option; B plays a short sideways pass to A, who now has the angle to split the mannequins to C between the lines. C carries on and scores in a mini goal. Rotate.', NULL, 'After some reps B chooses freely between the three patterns: a link pass via A or D, or the direct split pass to C.', 'As Practice 3.', '14 (7 per half)', 8, 14, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 70),
  ('Mannequin lane: go around to the free man', 'passing_unopposed', 'unopposed', 'in_possession', 59, 59, 'Situation 2 Session: Practice 5', 'Bielsa (Leeds United)', 'Reaching the free player between the lines by circulating the ball around the opposing block rather than through it.', 'Same halves, mannequins and mini goals as Practice 2 (30 x 40 yards).', 'D starts the move then runs round the inside mannequin, whatever C does. After A gets the return from B, D drops back at the right moment and plays a first-time pass inside to C, who carries forward and scores in a mini goal. Rotate.', NULL, NULL, 'As Practice 3.', '14 (7 per half)', 8, 14, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 80),
  ('Three-zone free player functional practice', 'positional_game', 'overload', 'in_possession', 60, 60, 'Situation 2 Session: Practice 6', 'Bielsa (Leeds United)', 'Moving the ball from the back line into a free player in the middle zone using the learned patterns against live defenders.', 'Area sized to age/level, split into low, middle and high zones (two pitches side by side in the diagram), 2 mini goals at each end. 7 whites: 3 in the low zone, 4 high; 3 red defenders in the middle.', 'The 3 low players try to find the free man in the middle zone with any of the earlier patterns. D and E make triangles, one dropping into the middle as the target while B and C give angles and G and F offer the go-around route. Once the free player receives he drives forward and shoots at the 2 mini goals; reds block passes, win it and counter into the 2 mini goals at the other end.', 'D and E must coordinate: one drops to be the free man while the other stays high, never both deep together.', NULL, 'As Practice 3.', '7v3', 10, 20, NULL, NULL, NULL, NULL, true, false, true, NULL, 90),
  ('6v6+1 three-zone game, 4 mini goals', 'small_sided_game', 'overload', 'in_possession', 61, 61, 'Situation 2 Session: Practice 7', 'Bielsa (Leeds United)', 'Breaking the first line of pressure and finding a neutral midfielder between the lines in a live game.', '30 x 40 yard area (adjust to age/level) with low and high zones holding 3v3 each and a 12 yard middle zone with 1 neutral; 2 mini goals at each end, a coach with balls at each end.', 'Coach feeds the whites, who try to get past the first line and into the neutral; the neutral turns to score in the 2 mini goals or slips a teammate running through. If they score, the coach at the other end feeds a new ball and play goes the other way. If reds win it they attack the opposite mini goals and become the attacking team, taking the coach''s next ball.', 'Defenders may only enter the middle zone once the neutral has received. Neutral should be a central midfielder.', NULL, NULL, '6v6+1', 13, 13, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 100),
  ('Build-up to the holding mid, 5v2 + mannequins', 'phase_of_play', 'overload', 'in_possession', 73, 73, 'Situation 3 Session: Practice 1', 'Bielsa (Leeds United)', 'Getting the ball from the back four into the defensive midfielder in space between the lines so he can turn and play forward.', '35 x 45 yard area (adjust to age/level), 2 mini goals at each end. 5 whites (back four + defensive midfielder) v 2 red forwards; 4 red mannequins stand in for midfielders. Coach serves from the back.', 'Coach passes to a white centre back; the back line moves the ball until the DM, positioned between the players and lines, receives, turns and scores in one of the 2 mini goals. Routes: direct through pass, a first-line pass then through pass, or going round via a link player when the lane is shut. If reds win it they score in the 2 mini goals at the other end.', NULL, NULL, 'First stage: easy to achieve, the point is to learn the options and positions. Leave the opponent''s shadow, sit between lines, receive half-turned.', '5v2 (+4 mannequins)', 7, 8, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 110),
  ('Holding mid build-up with extra link players', 'phase_of_play', 'overload', 'in_possession', 74, 74, 'Situation 3 Session: Practice 2', 'Bielsa (Leeds United)', 'Reading the picture and choosing the best route, direct or via link players, to free the defensive midfielder.', 'As Practice 1 (35 x 45 yards, 2 mini goals each end, mannequins) plus 2 white attacking midfielders starting in a high white zone and 2 red wide midfielders.', 'Same options as before, but the attacking midfielders can now also drop as link players (forward pass then lay-off) to get the ball to the DM, who turns and scores in a mini goal. Reds counter into the 2 mini goals at the other end if they win it.', 'Attacking midfielders start inside the white zone.', NULL, 'Leave the opponent''s shadow; get between lines and players to open lanes; read the situation and pick the best option; free man expects both direct passes and passes via link players; open body on the half-turn; good rhythm and synchronised movement.', '7v4', 11, 12, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 120),
  ('5(+2)v6 build-up game, 4 mini goals', 'phase_of_play', 'opposed', 'in_possession', 75, 76, 'Situation 3 Session: Practice 3', 'Bielsa (Leeds United)', 'Finding the defensive midfielder in space, or the attacking midfielders when he is denied, against a full midfield line.', 'As Practice 2 (35 x 45 yards, 2 mini goals each end) with 2 red central midfielders added: back four + DM, plus 2 attacking midfielders in the high zone, v 6 reds.', 'Scenario A: whites move the ball to the DM in the free central space; he scores in the 2 mini goals or, if pressed, finds an attacking midfielder to score. Attacking mids act as link players or receivers. Reds counter into the 2 mini goals at the other end.', NULL, 'Scenario B: a red central midfielder marks the DM; his stepping out opens space for an attacking midfielder to drop into, the ball goes wide to the full back, who plays a through pass to that attacking midfielder to score.', 'Leave the shadow; get between lines and players; read the situation and pick the best option; free man expects direct and link passes; receive half-turned; synchronised rhythm.', '5(+2)v6', 13, 14, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 130),
  ('7v6 game with receiving end zone', 'small_sided_game', 'overload', 'in_possession', 77, 77, 'Situation 3 Session: Practice 4', 'Bielsa (Leeds United)', 'Building through the defensive midfielder between the lines to reach attacking midfielders in an end zone and score in a full goal.', '35 x 45 yard area with a 35 x 10 yard low zone, a 35 x 25 yard middle zone where play happens and a 35 x 5 yard high receiving zone for the attacking midfielders; a goal and GK at each end.', '7 whites v 6 reds plus GKs, starting from the white GK. Whites work the ball forward and try to score; a goal after first finding the DM between the lines is worth more. If reds win it they counter and must score within 8-10 seconds, with no zone limits.', 'Goal = 1 point, goal after the DM received between the lines = 3 points. Reds may only enter the high zone after a white has received or dribbled into it; the GK cannot enter that zone. Red counter within 8-10 seconds.', NULL, 'As Practice 3.', '7v6 + GKs', 15, 15, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 140),
  ('Midfield switch pattern to target areas', 'combination', 'unopposed', 'in_possession', 85, 87, 'Situation 4 Session: Practice 1', 'Bielsa (Leeds United)', 'Rehearsing defensive and attacking midfielders swapping positions to open space between the lines.', '35 x 45 yard area with 4 white defenders and 3 white midfielders, mannequins as opposing forwards and midfielders, 3 white target areas (one central, two high) and 4 mini goals (2 high wide, 2 central further up).', 'Centre backs circulate the ball; when a defender steps forward with it, the DM makes his forward run and the attacking midfielder on that side drops into his space (the swap). Scenario A: the defender plays into the high or central target area to whoever is free (20 or 23), who finishes in one of the 2 nearest mini goals.', NULL, 'Scenario B: the full back carries forward and triggers the same strong-side swap, choosing the high or central target. Scenario C: swap with the weak-side attacking midfielder, so the only option is a pass into the central target area, then score in a mini goal.', 'Synchronised movements and accurate, well-timed passing to keep a good rhythm; receive open on the half-turn.', '7 (unopposed)', 7, 7, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 150),
  ('Midfield switch pattern vs 2 central mids', 'phase_of_play', 'overload', 'in_possession', 88, 89, 'Situation 4 Session: Practice 2', 'Bielsa (Leeds United)', 'Adding decision making to the midfield swap: read whether the opponent tracks the DM''s run.', 'As Practice 1 (35 x 45 yards, target areas, mini goals, mannequins) with 2 live red central midfielders.', 'As the swap happens, the defender on the ball reads the red midfielders. Scenario A: the red follows the DM forward, so the ball goes into the central target area for the dropping attacking midfielder, who scores in a near mini goal.', NULL, 'Scenario B: the red does not follow, so the defender (e.g. left back) plays into the high target area for the DM running forward, who scores in the mini goal.', 'Read the situation to make the right pass choice; synchronised movement and well-timed passing; open body on the half-turn.', '7v2', 9, 9, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 160),
  ('7v6+GK midfield switch tactical game', 'small_sided_game', 'overload', 'in_possession', 90, 90, 'Situation 4 Session: Practice 3', 'Bielsa (Leeds United)', 'Using midfield position swaps to create and exploit space between the lines in a live game.', '35 x 45 yard area with a 30 x 20 yard high zone (narrower than the pitch) holding a 30 x 8 yard white high target zone; goal and GK at the top, 2 mini goals at the coach''s end.', 'Coach starts with the white defenders, who aim to exploit the space made by the DM and an attacking midfielder switching. If the red midfielder tracks the DM, the dropping attacking midfielder receives low and central and then finds a teammate in the white high target zone, who shoots. If space is higher up, the ball goes straight into the zone for the forward-running DM. Reds who win it counter into the mini goals within 8-10 seconds.', 'Reds and their GK cannot enter the white high target zone. Counter within 8-10 seconds.', NULL, NULL, '7v6 + GK', 14, 15, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 170),
  ('Midfield three rotation pattern unopposed', 'combination', 'unopposed', 'in_possession', 99, 100, 'Situation 5 Session: Practice 1', 'Bielsa (Leeds United)', 'Using rotations of the three midfielders to create space and receive between the lines.', '35 x 45 yard area with 4 white defenders, 3 midfielders and 1 forward; 6 red mannequins as opposing forwards and midfielders, 2 white target areas in midfield and 2 mini goals at the far end. Coach serves.', 'Coach feeds a centre back and the back line circulates; when a defender steps forward with the ball the midfield three rotate. Scenario A: the DM (near the strong side) triggers it; the attacking midfielder who rotates in receives in the target area, plays into the forward, who lays off to an advanced midfielder to score in a mini goal.', NULL, 'Scenario B: the DM is too far from the strong side, so the attacking midfielder triggers the rotation; he receives in the target area, finds the forward, and the lay-off goes to the advanced player to score.', 'Synchronised movements and accurate timing for good rhythm; receive open on the half-turn; midfielders keep moving and the DM''s side (strong or weak) sets the shape of the triangle.', '8 (unopposed)', 8, 8, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 180),
  ('Midfield three rotations vs 2 central mids', 'phase_of_play', 'overload', 'in_possession', 101, 102, 'Situation 5 Session: Practice 2', 'Bielsa (Leeds United)', 'Choosing the right pass during midfield rotations based on how the opposing midfielders react.', 'As Practice 1 (35 x 45 yards, target areas, mannequins, 2 mini goals) with 2 live red central midfielders.', 'Scenario A: the defender on the ball reads the reds; if the red tracks the DM''s run, the ball goes to the attacking midfielder dropping into the target area, who turns and finds the forward, whose lay-off goes to the advanced midfielder to score. If the red does not track, the ball goes in behind the red midfielders through or around them; if neither is on, the back line keeps it and waits.', NULL, 'Scenario B: mirror on the left side; the left centre back steps forward, the DM is too far away, so the attacking midfielder triggers the rotation, receives in the target area and the move finishes via the forward''s lay-off.', 'Read the situation to choose the pass; synchronised movement and timing; receive open on the half-turn; in Scenario B the attacking midfielder moves quickly from the red midfielder''s blind side to get time to turn.', '8v2', 10, 10, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 190),
  ('8v8+GK midfield rotation game, attacking zone', 'small_sided_game', 'opposed', 'in_possession', 103, 103, 'Situation 5 Session: Practice 3', 'Bielsa (Leeds United)', 'Exploiting the space created by midfield-three rotations in a live directional game.', '35 x 45 yard area with a 25 x 25 yard high narrow zone holding the white midfield three and forward v 2 red central midfielders and 2 red centre backs; goal and GK at the top, 2 mini goals at the coach''s end.', '8v8 plus GK starting from the coach''s pass to a white defender. Whites move the ball into the space opened by the rotating midfield three and try to score in the big goal. If reds win it they counter and try to score in the mini goals within 8-10 seconds.', 'Once the reds win the ball there are no zone restrictions. Counter within 8-10 seconds.', NULL, 'As the previous practices.', '8v8 + GK', 17, 17, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 200),
  ('Striker runs in behind into target boxes', 'combination', 'unopposed', 'in_possession', 123, 124, 'Situation 7 Session: Practice 1', 'Bielsa (Leeds United)', 'Teach the centre forward to pick the right gap in a back line and time a run in behind to receive and finish.', 'Half a pitch with 10 mannequins standing in for the opposition shape (4 as the back line); white back four plus a holding midfielder in their positions, a forward in front of the mannequin line and a GK. Three target boxes are marked behind the mannequin line in the gaps where the forward has the edge.', 'The centre backs knock the ball between them until a full back or the holding midfielder receives and steps forward - that is the cue. The forward picks a gap between mannequins and bends his run in behind so the pass lands in the matching target box, then he finishes. Scenario A: full back plays into the central box; Scenario B: the holding midfielder plays and the forward shifts to the weak side to run between centre back and full back into the weak-side box.', 'Ball must be received inside a target box; forward must stay onside (roughly level with the mannequins) when the pass goes.', 'Scenario B: pass from the holding midfielder centrally, forward moves to the far side and attacks the weak-side box.', 'Forward stays alert and positions off the passer''s angle; run timed to stay onside; accurate pass into small boxes; good first touch and quick finish; when a full back has the ball he may attack central or weak-side box, when the ball is central only the weak-side box; rotate forwards to keep the tempo high.', '4 defenders, 1 defensive midfielder, 1-3 forwards + GK', 7, 9, 'Half a pitch', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Two-zone build-up then ball in behind', 'phase_of_play', 'opposed', 'in_possession', 125, 125, 'Situation 7 Session: Practice 2', 'Bielsa (Leeds United)', 'Free a player in build-up against pressure, then find the forward running in behind the back line.', 'Low zone: 4 white defenders and a holding midfielder against 4 red midfielders and a red forward, with 2 mini goals behind the whites. High zone: 4 mannequins as the red back line, a 30 x 10 yard target area behind them, a big goal with GK, the white forward, and coaches with balls at the sides and at the low end.', 'A coach feeds the whites, who work the ball to a team-mate with time on the ball (often the holding midfielder). On that cue the forward takes up a gap between two mannequins at a good angle and runs to receive in the target area and score.', 'If the reds win the ball in the build-up they have 8-10 seconds to score in the mini goals (5 whites defend). If the pass to the forward does not arrive in the target area, the nearest coach feeds the reds, who again have 8-10 seconds to hit the mini goals.', NULL, 'As in Practice 1: alert positioning, onside timing, accurate pass into the box, good touch and fast finish.', '6 whites + GK v 5 reds', 12, 12, 'Target area 30 x 10 yards in the high zone', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('11v11 three zones: score from runs in behind', 'conditioned_game', 'opposed', 'in_possession', 126, 126, 'Situation 7 Session: Practice 3', 'Bielsa (Leeds United)', 'Play the ball behind a set defensive line for the forward in a full-team game.', 'Two thirds of a pitch split into 3 zones (low, middle, high), goals and GKs at both ends; 11v11 with the red back four starting in the middle zone.', 'The white GK starts and the whites build in the low zone to find a free player (e.g. the left back), who then plays an accurate pass - often a diagonal lofted ball - over the line for the forward to run onto between the centre backs and score.', 'Normal goal 1 point; goal from a pass in behind for the forward 3 points. The 4 red defenders must stay in the middle zone while the ball is in the low zone; once the ball enters the middle zone they may drop deeper and the whites need another route.', NULL, 'Same as the previous practice.', '11v11', 22, 22, '2/3 of a full pitch, 3 zones', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Blind-side striker: drop, then spin or turn', 'combination', 'unopposed', 'in_possession', 134, 136, 'Situation 8 Session: Practice 1', 'Bielsa (Leeds United)', 'Teach the forward to hide behind the back line, drop onside at the right moment and choose between running in behind and receiving to turn.', 'Half a pitch with 10 mannequins as the opposition; white back four, a holding midfielder and a forward (2-3 forwards rotating) plus GK; pole gates near the byline on both flanks and target areas behind the mannequins.', 'The defenders circulate while the forward drifts behind the mannequin line on their blind side. When a defender or the holding midfielder receives and steps up, the forward comes back onside. Scenario A: the full back has a good angle and the forward runs in behind into the central area to score. Scenario B: the holding midfielder has the ball and the forward goes wider, running between centre back and full back mannequins into the wide target area. Scenario C: no angle for a lofted ball, so the forward drops between the lines, receives, turns and passes through the pole gate (as if to a winger in behind) or drops only a little, receives half-turned and shoots.', 'Forward must start from an offside (blind-side) position and get back onside before the pass.', 'Scenarios B and C as described (wide target area; drop, turn and pass through the gate or shoot).', 'Synchronisation and communication between passer and forward; correct decision and well-timed run; accurate passes into the exact spaces needed for a chance.', '4 defenders, 1 defensive midfielder, 1-3 forwards + GK', 7, 9, 'Half a pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('5v5 build-up, forward drops or spins', 'phase_of_play', 'opposed', 'in_possession', 137, 137, 'Situation 8 Session: Practice 2', 'Bielsa (Leeds United)', 'Free a player in build-up, then read whether the forward should attack the space in behind or drop to feet.', 'Low zone 5v5 (4 white defenders + holding midfielder v 4 red midfielders + red forward) with 2 mini goals behind the whites; high zone with 4 mannequins, pole gates, a goal and GK, and the white forward starting behind the mannequins. Coach with balls at the low end.', 'The coach plays in and the whites move the ball until someone (e.g. the holding midfielder) can play forward; the forward then drops. With a good passing angle he spins and attacks the box to receive and score; without one he drops between the lines to receive to feet.', 'Reds who win the ball have 8-10 seconds to score in the mini goals. An inaccurate pass to the forward means the GK gives the reds a new ball and the same 8-10 seconds apply.', 'If it is too hard for the whites to find time on the ball, remove a red to make it 5v4 in the low zone.', 'As Practice 1: synchronised timing, correct decision, accurate passing.', '6 whites + GK v 5 reds', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('11v11 two zones: forward drops at right moment', 'conditioned_game', 'opposed', 'in_possession', 138, 138, 'Situation 8 Session: Practice 3', 'Bielsa (Leeds United)', 'Apply the forward''s blind-side positioning and timed drop or run in a full game.', 'Two thirds of a pitch split into 2 zones, goals and GKs at both ends; 11v11 with the white forward starting in the high zone in an offside position.', 'The white GK starts, the whites build in the low zone and the forward waits for the right moment to drop or run in behind; the whites try to score.', 'Goal 1 point; goal after the forward uses one of the options from the earlier practices 3 points. Red defenders may not enter the high zone unless a white player receives there. Reds who win the ball counter and must score within 8-10 seconds.', NULL, 'Read the defenders'' positioning and choose the right option; time the drop and the run in behind; synchronised movement, communication, quick accurate passing and finishing.', '11v11', 22, 22, '2/3 of a full pitch, 2 zones', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Pass between the lines via link player', 'passing_unopposed', 'unopposed', 'in_possession', 153, 153, 'Situation 9 Session: Practice 1', 'Bielsa (Leeds United)', 'Rehearse finding a free player between the lines, directly or through a link player.', 'Two halves run side by side at once, each with mannequins, a marked middle zone (''between the lines'') and blue cones; 5 players A-E per half, A at the bottom with the ball, E behind him, D at the far end.', 'A carries forward; B drops back while C opens up in the middle zone. A either passes straight to C or uses B as a link; C then plays D, who has moved into a free lane on the other side. A moves to the nearest blue cone to become the next link, B goes to the middle blue cone as the next receiver and C runs to D''s end. The pattern then comes back the other way starting with D and finishing with E.', NULL, NULL, NULL, '10 (5 per half)', 10, 10, NULL, NULL, NULL, NULL, false, false, true, NULL, 270),
  ('Free the player between the lines, 15 yd zone', 'phase_of_play', 'opposed', 'in_possession', 154, 156, 'Situation 9 Session: Practice 2', 'Bielsa (Leeds United)', 'Read the situation and get the ball to a free attacking midfielder between the lines, then attack the space in behind.', '35 x 50 yard area: a 35 x 15 yard low zone and a 35 x 15 yard middle zone, a big goal with GK at the top and 2 mini goals at the bottom. Whites: holding midfielder and both full backs as second-line players, two attacking midfielders, forward and two wingers; 4 red midfielders in the middle zone and 4 mannequins as the back line.', 'The holding midfielder and full backs move the ball until they can reach an attacking midfielder between the lines, who plays the key pass in behind for a team-mate. Scenario A: direct pass from the holding midfielder. Scenario B: lane blocked, so the forward drops as a link player and sets it to the free attacking midfielder, who can release a winger to cross. Scenario C: reds compact, so the ball goes round them to the full back, and the winger drops to link inside to the attacking midfielder.', 'Whites must score within 5 seconds of the key pass. Reds who win the ball try to score in the 2 mini goals within 8-10 seconds.', 'Scenarios B (forward as link player) and C (play round the opponents, winger as link).', 'Choose the right way into the attacking midfielders; they must be ready to receive directly and through link players; synchronised forward and winger movement when linking; finish quickly once the free player has it.', '8 whites + GK v 4 reds (+4 mannequins)', 13, 13, '35 x 50 yards (two 35 x 15 yard zones)', 46.0, 32.0, NULL, true, true, true, NULL, 280),
  ('Three-zone game: find midfielders between lines', 'phase_of_play', 'opposed', 'in_possession', 157, 157, 'Situation 9 Session: Practice 3', 'Bielsa (Leeds United)', 'Move the ball into an attacking midfielder between the lines under real defensive pressure, then create a chance.', '35 x 50 yard area split into three zones, big goal + GK at the far end, 2 mini goals at the near end; whites build from the back against 4 added red defenders plus red midfielders.', 'Whites build up and try to score in the big goal; extra reward if the ball went through an attacking midfielder between the lines first. Reds defend mainly in the middle zone and counter to the mini goals when they win it.', 'Goal = 1 point, goal after an attacking midfielder received between the lines = 3 points. Reds may only enter the high zone once a white receives there. Reds must finish a counter within 8-10 seconds.', NULL, 'As in the previous practices: support angles, link players, quick tempo.', '8v8 + GK', 17, 17, '35 x 50 yards', 45.7, 32.0, NULL, true, true, true, NULL, 290),
  ('11v11 with middle zone, play to midfielders', 'conditioned_game', 'opposed', 'in_possession', 158, 158, 'Situation 9 Session: Practice 4', 'Bielsa (Leeds United)', 'Apply the build-up to attacking midfielders between the lines in a full-team game.', 'Two thirds of a pitch with a 15 yard middle zone marked out where the red midfielders and defenders set up to defend; goals and GKs at both ends.', 'Play starts with the white GK; whites work the ball to an attacking midfielder between the lines who then plays a key pass in behind the back line.', 'Goal = 1 point; goal after an attacking midfielder received between the lines and played a key pass in behind = 3 points.', NULL, 'Read the situation and choose the right way to reach the midfielders; midfielders ready to receive directly or via a link player; synchronised forward and winger movements; fast, accurate passing and quick finishing.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Forward drops, midfielder runs in behind', 'combination', 'unopposed', 'in_possession', 166, 167, 'Situation 10 Session: Practice 1', 'Bielsa (Leeds United)', 'Rehearse the forward dropping off to receive or pull a defender, with an attacking midfielder timing a run into the space behind.', '35 x 45 yard area halved lengthways so two groups work at once; mannequins mark the opponents, a low target box at the start and high target boxes behind the defender mannequins, goal + GK at the end.', 'E plays long into the low box for A, who touches inside and passes to B between mannequins. Phase 1: forward D drops to get free while C runs; B either finds D''s feet (D turns and slips C in) or lofts it over the mannequin for C to finish. Phase 2 adds a second attacking midfielder C2: D lays square to C2 who plays C through, or D plays back to B for a lofted ball to C or C2.', NULL, 'Phase 2 adds a second attacking midfielder and two set combinations (square lay-off + through ball, or back pass + lofted ball).', 'Synchronise the midfielders'' runs with the forward''s movement and stay onside; read the forward''s body shape; accurate passing at high tempo; quick, clean finishing.', '2 groups of 5-6 + GK', 11, 14, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 310),
  ('Forward drops vs 2 active centre backs', 'combination', 'overload', 'in_possession', 168, 169, 'Situation 10 Session: Practice 2', 'Bielsa (Leeds United)', 'Choose between the forward''s feet and the space in behind depending on how the two centre backs react to the forward dropping.', 'Goal + GK, 2 live red centre backs and 8 mannequins for the rest of the defending team; a marked receiving box for the defensive midfielder; 2 white centre backs start with balls, plus forward, wingers and attacking midfielders.', 'White centre backs pass between themselves then find the defensive midfielder in his zone as the forward drops. If the centre backs hold their zone, the midfielder feeds the forward''s feet and he turns to slip a runner in (e.g. winger crosses for a midfielder). If a centre back follows the forward, the midfielder lofts a ball into the gap for an attacking midfielder; if the defender presses after the pass to the forward, use a square-pass or back-pass-and-lofted-ball combination.', NULL, 'Scenario A (centre backs stay in their zone) and Scenario B (one centre back follows the forward).', 'Read how the centre backs react before choosing feet or space in behind; forward, midfielders and wingers move in sync; accurate passing at high tempo.', '8 attackers v 2 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Forward drops vs an active back four', 'phase_of_play', 'overload', 'in_possession', 170, 170, 'Situation 10 Session: Practice 3', 'Bielsa (Leeds United)', 'Exploit the space a dropping forward creates against a full live back four.', 'Two thirds of a pitch, same layout as the previous practice but the two red full backs are now live, giving an active back 4 plus GK; midfield mannequins remain.', 'Whites build from the centre backs to the defensive midfielder, who reads the defenders'' reaction and picks the pass (forward''s feet, lofted ball in behind, or combination) to break the back four and score.', NULL, NULL, 'Same as Practice 2.', '8 attackers v 4 + GK', 13, 13, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('11v11: dropping forward combinations', 'conditioned_game', 'opposed', 'in_possession', 170, 170, 'Situation 10 Session: Practice 4', 'Bielsa (Leeds United)', 'Use the dropping-forward combinations from the session in a full game.', 'Full 11v11 game (layout as the session''s earlier games).', 'Normal game; whites earn a bonus for scoring through one of the session''s combinations, reds counter when they win it.', 'Goal = 1 point, goal from one of the session''s combinations = 3 points. Reds must finish a counter within 8-10 seconds.', NULL, NULL, '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Winger runs in behind full back, cross', 'combination', 'unopposed', 'in_possession', 186, 187, 'Situation 12 Session: Practice 1', 'Bielsa (Leeds United)', 'Time the winger''s run so he receives behind the full back close to the line between full back and goal, then cross for runners.', 'Half a pitch with goal + GK, mannequins for the opposing back line, midfield and wide full backs, a central cone for the defensive midfielder; 2 centre backs with balls, wingers wide, attacking midfielders inside.', 'Centre backs pass across; when one steps in with the ball the defensive midfielder drops between the central mannequins to receive and turn. The winger starts early, gets level with the full-back mannequin as the pass is played and runs onto a ball in behind, then crosses for the far-side attacking midfielder. Phase 2: full-back mannequins move narrow, so the passer either lofts it in behind or plays wide to the winger''s feet near the touchline.', NULL, 'Phase 2/2: narrow full-back mannequins remove the ground through ball; next player steps up off the cone to rotate.', 'Midfielders receive in the gaps between mannequins; well-timed winger runs to stay onside; accurate passing and finishing.', 'about 8 + GK', 9, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Winger checks wide after run, cross', 'combination', 'unopposed', 'in_possession', 188, 188, 'Situation 12 Session: Practice 2', 'Bielsa (Leeds United)', 'Train the safer option: the winger feints in behind, then breaks wide to receive and cross.', 'Same mannequin layout as Practice 1.', 'A centre back steps in, the attacking midfielder drops between mannequins to receive, the winger makes a diagonal run at the full-back mannequin then switches out wide to take the pass and cross for the attacking midfielder on the far side.', 'Rotation: each attacking midfielder drops to set the winger up, returns, then makes the forward run to finish the next cross from the other side, then swaps with the player waiting behind the mannequin.', NULL, 'As Practice 1.', 'about 8 + GK', 9, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Wingers in behind vs 5 live defenders', 'phase_of_play', 'overload', 'in_possession', 189, 189, 'Situation 12 Session: Practice 3', 'Bielsa (Leeds United)', 'Find the free midfielder, then release a winger in behind after reading the full back''s position.', 'Two thirds of a pitch: a high zone with goal + GK, 2 red full backs and centre-back mannequins, and a 35 x 25 yard middle zone with a 5v3; 2 mini goals behind the start line; coach serves.', 'Coach plays in; whites work the ball to a free attacking or defensive midfielder who has time to find a winger running in behind the red full back. The 3 red midfielders try to win it and score in the mini goals.', 'Wingers must finish within 3-4 seconds of receiving in the high zone. Red full backs may only enter the high zone to defend their goal.', NULL, 'Find the free midfielder quickly; read the full back''s positioning; well-timed winger runs to stay onside; quick, accurate passing and finishing.', '5v3 in midfield + 2 wingers v 2 full backs + GK', 13, 15, 'middle zone 35 x 25 yards on 2/3 of a pitch', 22.9, 32.0, NULL, true, true, true, NULL, 370),
  ('11v11: wingers receive in behind', 'conditioned_game', 'opposed', 'in_possession', 190, 190, 'Situation 12 Session: Practice 4', 'Bielsa (Leeds United)', 'Apply the winger runs in behind the full back in a full game.', 'Same area as Practice 3 (2/3 pitch with high zone), 11v11 with 2 big goals + GKs.', 'Starts with the white GK; whites score for 1, or for 3 after a successful pass to a winger in behind the back line. Reds counter on winning the ball.', 'First 10 minutes red defenders must stay outside the high zone until the ball enters it; restriction then removed. Reds counter within 8-10 seconds.', 'Drop the high-zone restriction after 10 minutes.', 'Read the full back''s position to choose; well-timed runs to stay onside; quick, accurate passing and finishing.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Forward''s runs to meet crosses (unopposed)', 'finishing', 'unopposed', 'in_possession', 199, 200, 'Situation 13 Session: Practice 1', 'Bielsa (Leeds United)', 'Train the forward to choose and attack the right space for a cross, and the crosser to read it.', 'Final third with goal + GK; 2 wide mannequins as full backs and 3 in the box as the other defenders; wingers and full backs on cones wide with balls, attacking midfielders central, forward at the edge of the box.', 'A winger plays a one-two with the attacking midfielder, receives past the mannequin and crosses. The forward moves just before the cross and attacks a space: between centre back and full back for a high cross (Scenario A), or a sharp change of direction across the near-post mannequin for a short low cutback (Scenario B). Next cross comes from the other flank.', NULL, 'Scenario A aerial crosses to centre/far post; Scenario B aerial or low crosses to the near post; full backs also take turns crossing.', 'Crosser and forward communicate with their eyes so the ball goes to the chosen space; accurate crossing and finishing.', 'about 8 + GK', 9, 12, 'final third', NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Forward''s runs to meet crosses (opposed)', 'finishing', 'opposed', 'in_possession', 201, 202, 'Situation 13 Session: Practice 2', 'Bielsa (Leeds United)', 'The forward finds space for the cross against a live centre back.', 'As Practice 1 but the box is split into two areas, each with one live red centre back; a mannequin is the far centre back.', 'When the winger gets the return pass, the forward first moves to draw the centre back, then attacks the free space: blind-side run between the centre backs (Scenario A) or across the front of the defender to the near post for a low cross (Scenario B). Alternate flanks and crossers.', NULL, 'Defender starts passive and becomes more active as the practice goes on.', 'Crosser and forward communicate visually; accurate crossing and finishing.', 'about 8 + 2 defenders + GK', 11, 14, 'final third', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Forward + weak-side midfielder cross runs', 'finishing', 'unopposed', 'in_possession', 203, 204, 'Situation 13 Session: Practice 3', 'Bielsa (Leeds United)', 'Coordinate the forward and weak-side attacking midfielder so they fill different spaces for the cross.', 'Same as Practice 1 (wide and box mannequins, goal + GK).', 'Run as Practice 1 with two runners: if the forward attacks between the centre backs, the midfielder takes the gap between centre back and full back (Scenario A); if the forward goes between centre back and full back, the midfielder fills the gap between the centre backs (Scenario B).', NULL, 'Scenario A and B swap which space each runner takes; alternate flanks.', 'Visual communication between crosser and runners; accurate crossing and finishing.', 'about 8 + GK', 9, 12, 'final third', NULL, NULL, NULL, true, true, true, NULL, 410),
  ('Full box attack: forward, midfielders, winger', 'finishing', 'unopposed', 'in_possession', 205, 206, 'Situation 13 Session: Practice 4', 'Bielsa (Leeds United)', 'Fill all the key cross spaces at once: between defenders, far post and edge of the box.', 'Same mannequin set-up as Practice 1.', 'Full back, winger or attacking midfielder delivers. With a wide crosser, the strong-side midfielder holds the edge of the box for cutbacks while the forward, weak-side midfielder and weak-side winger (back post) attack the box (Scenario A). With a midfielder crossing from wide, he can cut back for the other midfielder arriving at the edge (Scenario B).', NULL, 'Scenario A cross from a wide player; Scenario B cross or cutback from an attacking midfielder.', 'Visual communication; the two attacking midfielders agree who holds the edge of the box and who runs in; accurate crossing and finishing.', 'about 9 + GK', 10, 12, 'final third', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Zonal crossing game with wide channels', 'small_sided_game', 'opposed', 'in_possession', 207, 208, 'Situation 13 Session: Practice 5', 'Bielsa (Leeds United)', 'Synchronise the cross with runs into good positions in the box during a game.', 'Pitch with two goals + GKs and a wide channel on each side; each team has 2 wingers in the channels plus 7 central players including 3 defenders.', 'Teams make at least 3 passes then find a winger in a wide channel; the winger (or an attacking midfielder who moves wide) crosses or cuts back while teammates attack the best spaces in the box.', 'Minimum 3 passes before playing wide. Only the wingers and the attacking team''s attacking midfielders may enter the wide channels.', 'Scenario A cross from the winger; Scenario B attacking midfielder goes wide and cuts back.', 'Crosser and forward communicate visually; accurate crossing and finishing.', '7 (+2) v 7 (+2) + GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Advanced full back 2v1 wide patterns to finish', 'combination', 'unopposed', 'in_possession', 221, 223, 'Situation 14 Session: Practice 1', 'Marcelo Bielsa (Leeds United)', 'Rehearse the patterns that exploit a 2v1 out wide when the full back receives high, either attacking the space behind the opposing full back or the key central area, ending in a cross and finish.', 'Full pitch attacking half with 10 mannequins as a 4-4-2 back eight/front two plus 3 in the box; yellow side-line zones for the full backs; white players on cones in their positions (2 per cone for wingers and attacking midfielders); centre backs start with balls near halfway.', 'A centre back passes across to the other, who finds the full back in the yellow wide zone. Scenario A: winger cuts inside then runs behind the full back mannequin to receive and cross while weak winger, weak and strong attacking mids fill far post, between defenders and edge of box. Scenario B: winger receives, goes inside, links via attacking mid for the full back''s overlap and cross. Scenario C: attacking mid receives between the lines and lofts a switch to the weak winger at far post. Scenario D: centre back plays long to winger, who drops, drives inside while full back overlaps to cross.', NULL, 'Scenarios A-D; further options from the analysis pages can be added.', 'Use the 2v1 to exploit space on the flank or inside between the lines; quick accurate passing, combination play, runs and finishing.', 'Attacking unit (CBs, FBs, wingers, AMs, forwards) with doubled positions + GK', NULL, NULL, 'Attacking half of full pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Advanced full back 2v1 vs back four then midfield', 'phase_of_play', 'overload', 'in_possession', 224, 225, 'Situation 14 Session: Practice 2', 'Marcelo Bielsa (Leeds United)', 'Read the opposing full back and strong-side centre back to pick the right combination after the full back receives high: in behind the full back or inside between the lines.', 'Same set-up as Practice 1 but with 4 live red defenders (back four) and remaining mannequins; centre backs start near halfway with balls; yellow wide zones for the full backs.', 'Phase 1: centre backs work the ball to the advanced full back; whites read whether the red full back steps up or the centre back shifts and choose to go behind the full back for a cross or inside for a key pass. Phase 2: two red central midfielders are added (6 active defenders), so when the centre back covers the winger''s run, the full back plays inside to the attacking mid between the lines to play the key pass.', NULL, 'Phase 2 adds 2 red central midfielders.', 'Decision making is key: read the reaction of the full back and centre back; quick accurate passing, combination play, runs and finishing.', 'About 10 attackers + GK vs 4 then 6 defenders', NULL, NULL, 'Attacking half of full pitch', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Wide 2v1 tactical game with full back zones', 'conditioned_game', 'opposed', 'in_possession', 226, 226, 'Situation 14 Session: Practice 3', 'Marcelo Bielsa (Leeds United)', 'In a game, create a 2v1 out wide with the full back and then exploit the free space wide or inside.', 'Two thirds of a pitch, full goal with GK for whites to attack, two mini goals on the far line for reds; two wide zones marked in the final third.', 'Whites build from the back and try to score after making a 2v1 out wide and attacking the space behind or inside; reds defend and counter to the mini goals.', 'Only the red team''s full backs may enter the wide zones.', 'Normal 11v11 in two thirds of a pitch with no zones; a goal after exploiting a wide 2v1 counts 3.', 'Decision making: full back reads the situation and exploits the 2v1 to receive behind the opposing full back with an overlap; quick accurate passing, combinations, runs, finishing.', '11v11', 22, 22, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Twin-channel passing pattern behind the line', 'combination', 'unopposed', 'in_possession', 243, 244, 'Situation 15 Session: Practice 1', 'Marcelo Bielsa (Leeds United)', 'Rehearse wide combinations between defensive mid, full back, winger and attacking mid to get the ball behind the defensive line and finish.', '40 x 60 yard area split in half lengthways, two goals with GKs; 8 mannequins as defenders and midfielders, front and back mannequins 10 yards apart; extra players at full back, winger, attacking mid and forward; runs on both halves at once.', 'Defensive mid passes to the full back, who drops off his cone. Scenario A: winger drops, receives half-turned, full back overlaps, attacking mid receives between the lines and plays the ball in behind (to overlapping full back, winger or forward) to finish. Scenario B: winger receives facing his own goal, full back runs to support behind him for a back pass, then plays a through or lofted ball for the attacking mid''s run.', 'Next repetition by the second player in each position; first group returns to the mannequins.', 'Scenario A (winger can turn) and Scenario B (winger back to goal).', 'Decide by the winger''s body shape: open lets him turn, back to goal means the full back offers support behind; synchronise movements; quick accurate passing and finishing.', '2 groups of about 5 + 2 GKs, with spares', NULL, NULL, '40 x 60 yards', 36.6, 54.8, NULL, true, true, true, NULL, 470),
  ('Support the attacking mid then switch long', 'combination', 'unopposed', 'in_possession', 245, 245, 'Situation 15 Session: Practice 2', 'Marcelo Bielsa (Leeds United)', 'Give support to an attacking midfielder who receives but cannot turn, then switch with a long pass into the weak side behind the line.', 'Attacking half with 4 mannequins on each side (full back, wide mid, central mid, weak centre back); 3 small target areas inside the box; GK in goal.', 'Defensive mid passes to the full back, who finds the winger and overlaps. Winger drives inside and passes to the attacking mid, who receives beside the mannequin and lays off to the winger or the advancing defensive mid; that player switches with a long pass into a weak-side target area for the other attacking mid or winger, who finishes.', NULL, NULL, 'Support play around a receiver who cannot turn; accurate long switch.', 'About 8 attackers + GK', NULL, NULL, 'Attacking half of full pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Wide combinations vs centre back and full back', 'combination', 'opposed', 'in_possession', 246, 247, 'Situation 15 Session: Practice 3', 'Marcelo Bielsa (Leeds United)', 'Pick the right wide combination for the full back, winger and attacking mid against two live defenders.', 'Half pitch split in half lengthways with a 15 x 25 yard wide area on each side; in each, 2 red defenders (centre back and full back) and 2 mannequins (central and wide mid); whites full back, winger, attacking mid, plus a forward more central acting as an outside player; two goals with GKs; spare whites waiting.', 'Defensive mid starts by passing to the full back. Scenario A: winger turns, full back overlaps, and the next pass goes to the attacking mid if the centre back stays or in behind if he steps to mark. Scenario B: winger under pressure plays back to the supporting full back, who plays through or lofts the ball behind the full back for the attacking mid, who crosses for the forward.', 'Waiting whites take the next repetition.', 'Scenario A (winger turns) and Scenario B (winger plays back under pressure).', 'Attack at top speed; decide on the defenders'' reaction; synchronise movements; quick accurate passing and finishing.', '3+1 attackers vs 2 defenders per side + GKs', NULL, NULL, 'Half pitch; 15 x 25 yard wide areas', 22.9, 13.7, NULL, true, true, true, NULL, 490),
  ('Break through wide pressure zone, cross and finish', 'phase_of_play', 'overload', 'in_possession', 248, 248, 'Situation 15 Session: Practice 4', 'Marcelo Bielsa (Leeds United)', 'Carry out wide attacking combinations at speed before the opposing central midfielder can drop in, finishing with a cross.', 'As Practice 3 (half pitch, two wide areas, two goals with GKs) but red central and wide midfielders are live on both sides; red central mids start on cones to leave space between the lines; 2 mini goals near halfway for reds; whites have defensive mid, full back, winger, attacking mid and forward.', 'White defensive mid passes to the full back and enters, making 4+1 v 4. Whites read whether the winger can turn and the reactions of centre back and full back to choose the combination, then cross and finish. If reds win it they counter to the mini goals; the defensive mid is the safety player.', 'Reds score in the 2 mini goals on a turnover.', NULL, 'Top speed before the central mid drops back; read the tactical situation when the winger receives.', '4+1 v 4 per side + GKs', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('8v8 wide combinations or switch game', 'conditioned_game', 'opposed', 'in_possession', 249, 249, 'Situation 15 Session: Practice 5', 'Marcelo Bielsa (Leeds United)', 'Apply the wide combinations and weak-side switches from the session in a game.', 'Half pitch with two wide areas marked near the side-lines; full goal with GK; 3 mini goals on halfway for reds; whites start with a defensive mid (5 or 23) on the ball.', 'One white defensive mid makes the first pass and joins (the other stays outside); whites choose options based on opponents'' reactions, e.g. winger turns inside, full back overlaps, attacking mid lays back first time to the defensive mid, who lofts the ball for the other attacking mid. Reds win the ball and counter to any of the 3 mini goals.', 'No restriction on who enters the wide areas; reds score in 3 mini goals.', NULL, 'Use all options from the earlier practices and analysis.', '8v8 (+GK)', 17, 18, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Deep full back combination options to finish', 'combination', 'unopposed', 'in_possession', 262, 263, 'Session (Situation 16): Practice 1', 'Bielsa (Leeds United)', 'Rehearse wide combinations when the full back gets the ball in a deep position, with the wide midfield mannequin pushed high.', '40 x 60 yard area split into two halves, a goal on each, mannequins as the opposing wide midfielder (advanced) and full back about 15 yards apart, plus central mannequins; mirror groups on left and right.', 'Defensive midfielder plays to the deep full back, who finds the winger dropping to receive; from there the group runs a set option, e.g. forward slides across between the lines and dribbles at goal, or winger slips the attacking midfielder in behind the full back mannequin. Waiting players take the next turn.', 'Both sides run at the same time; follow the pattern shown.', 'Scenario A winger drops and progresses; Scenario B chain movement of attacking midfielder and full back (lofted ball in behind, or wall pass and final ball for the forward); Scenario C attacking midfielder overlaps the winger who cuts inside, or winger plays a one-two with the forward to shoot.', NULL, 'about 7 attackers per side, two sides', 12, 18, '40 x 60 yards', 54.9, 36.6, NULL, true, true, true, NULL, 520),
  ('Deep full back wide combinations vs 2 defenders', 'phase_of_play', 'opposed', 'in_possession', 264, 264, 'Session (Situation 16): Practice 2', 'Bielsa (Leeds United)', 'Read two live defenders and pick the right wide combination when the full back receives deep.', 'Half pitch split vertically; marked wide areas with a 5 yard low zone. In each wide area a red centre back and full back are live, with mannequins for the central and (advanced) wide midfielder. Two goals with keepers; runs both sides.', 'Defensive midfielder passes to the full back in the low zone. If the winger is free he receives; if he is tightly marked, the full back lofts the ball behind the red full back for the attacking midfielder''s run. The move ends with the forward finishing.', NULL, NULL, 'Attackers choose the option from the defenders'' reaction.', 'attackers vs 2 defenders per side', 14, 20, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Deep full back break-through pressure zone game', 'phase_of_play', 'opposed', 'in_possession', 265, 265, 'Session (Situation 16): Practice 3', 'Bielsa (Leeds United)', 'Break through a wide pressure zone with combinations after the full back gets the ball deep, and react on losing it.', 'As the previous practice but red central and wide midfielders are now live; two big goals with keepers at the top and two mini goals by the halfway line for the reds.', 'Defensive midfielder passes to the full back and then joins in, making 4+1 v 4 on each side. Whites pick the best combination to break through and score; if reds win it they counter to the mini goals and whites try to stop them.', 'Both sides played at once.', NULL, 'Movements at full speed; decisions based on defenders; synchronised timing; quick accurate passing and finishing.', '4+1 v 4 per side', 18, 22, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 540),
  ('8v8 tactical game with side zones', 'conditioned_game', 'opposed', 'in_possession', 266, 266, 'Session (Situation 16): Practice 4', 'Bielsa (Leeds United)', 'Apply the deep full back wide combinations in a game.', 'Half pitch, two wide channels marked near the touchlines each with a low zone; one big goal with keeper for whites to attack, three mini goals for reds.', '8v8 plus keeper. A white defensive midfielder starts by passing to a full back in the low zone, then joins; whites use the trained options to beat the press (e.g. winger receives and turns as the attacking midfielder runs off the centre back and the forward fills the space). Reds win it and counter to any mini goal.', 'Wide channels are guides only; anyone may enter them.', NULL, NULL, '8v8 (+GK)', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Key central area passing grids', 'passing_unopposed', 'unopposed', 'in_possession', 277, 278, 'Session (Situation 17): Practice 1', 'Bielsa (Leeds United)', 'Rehearse passes from a deep full back into the key central area depending on whether the opposing centre back steps up or holds.', 'Four 20 x 30 yard grids each with 4 mannequins (wide midfielder, full back, centre back, central midfielder) and a 5 x 5 yard target square; in the low grids the centre back mannequin is high, in the high grids the mannequins are 10 yards apart.', 'A passes to B who carries forward while C drops and D moves. Low grids: B plays into C''s feet for a lay-off and pass into the target square for D, or chips straight into the square. High grids: B finds C between the mannequins, C turns and feeds D. D dribbles through the cones and passes to A at the far end; rotate A-B-C-D-A.', 'Low grids allow either of two combinations; high grids only the one shown.', NULL, NULL, '4 per grid, 16 total', 16, 20, 'four 20 x 30 yard grids', 27.4, 18.3, NULL, false, false, true, NULL, 560),
  ('Attack space behind full back passing grids', 'passing_unopposed', 'unopposed', 'in_possession', 279, 279, 'Session (Situation 17): Practice 2', 'Bielsa (Leeds United)', 'Rehearse getting the ball behind an opposing full back or between the mannequins from a deep full back.', 'Same four grids, all with mannequins 10 yards apart; two target squares per grid, one between the mannequins and one behind the full back mannequin.', 'Left side: A to B who carries and passes into the square behind the full back for D. Right side: A to B, D runs behind the mannequin and C drops between; B finds C who turns and plays into D''s path. D dribbles through the cones and passes to A opposite; rotate.', 'Either of the two combinations may be used.', NULL, NULL, '4 per grid, 16 total', 16, 20, 'four 20 x 30 yard grids', 27.4, 18.3, NULL, false, false, true, NULL, 570),
  ('Attack behind centre back vs 2 centre backs', 'phase_of_play', 'opposed', 'in_possession', 280, 281, 'Session (Situation 17): Practice 3', 'Bielsa (Leeds United)', 'Read a live centre back''s reaction and exploit the space between the lines or behind him.', 'Half pitch with two marked central areas, mannequins for the rest of the back line and midfield, one live red centre back per side; two goals with keepers; runs both sides.', 'Defensive midfielder passes to the full back while the attacking midfielder moves to receive between the lines. If the centre back holds, the attacking midfielder receives, turns and slips in the forward; if he steps in early, the full back lofts it behind him. Forwards finish quickly.', NULL, 'Phase 1B: centre back presses after the pass, so the full back takes a lay-off and lofts it in behind. Phase 2: full back mannequins pushed higher, attacking midfielder runs behind the full back; if the centre back does not follow he gets a lofted ball, if he does the pass goes to the forward. Coach may serve to the full backs instead.', NULL, 'attackers vs 1 centre back per side', 12, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Key central area functional vs back 4', 'phase_of_play', 'opposed', 'in_possession', 282, 283, 'Session (Situation 17): Practice 4', 'Bielsa (Leeds United)', 'Choose the best route into the key central area against a live back four depending on where the opposing full back is.', 'Half pitch with two central areas and horizontal lines out wide that show whether the red full back is deep or advanced; 8 white outfielders (no centre backs) v 4 red defenders and keeper.', 'Defensive midfielder starts; when a full back receives, the attacking midfielder moves between the lines. If the red full back is deep, he looks to receive and turn, or if marked the forward or weak side attacking midfielder attacks space for a long ball. Whites finish with a shot or a cross.', 'Two whites per position allowed so the next wave goes once a shot is taken or reds win it.', 'Scenario B: red full back advanced, attacking midfielder runs wide behind him; if the centre back ignores the run the ball goes to him, if he tracks it the pass goes to the forward or weak side attacking midfielder, who turns and attacks (e.g. cross to the far post winger).', 'Synchronised movement; decide from the strong side defenders'' reaction.', '8v4+GK', 13, 21, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 590),
  ('Key central area conditioned 8v8 game', 'conditioned_game', 'opposed', 'in_possession', 284, 284, 'Session (Situation 17): Practice 5', 'Bielsa (Leeds United)', 'Use the deep full back solutions into the key central area in a game.', 'Half pitch, one big goal with keeper, two mini goals near halfway for reds; two central areas and horizontal wide lines marked (can be removed).', '8v8 plus keeper starting from the white defensive midfielder; whites combine through the key central area to score, reds win it and counter.', 'White goal 1 point, 3 points if it follows a trained combination through the reds'' defence; reds must score in the mini goals within 8-10 seconds of winning the ball.', 'Remove the marked areas and lines.', NULL, '8v8 (+GK)', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Switch to full back behind midfield line', 'passing_unopposed', 'unopposed', 'in_possession', 295, 295, 'Session (Situation 18): Practice 1', 'Bielsa (Leeds United)', 'Full backs make diagonal runs to get the switched ball behind the midfield line in the key central area.', 'Half pitch split vertically; on each side two mini goals and two mannequins as the opposing central and wide midfielders; wide players with balls start the practice.', 'Wide player passes to the midfielder, who drops, receives and plays a diagonal ball between the two mannequins for the full back''s timed run. The full back carries forward and shoots into a mini goal.', 'Two players in each midfield spot rotate; wide starters rotate with the full backs.', NULL, 'Quick accurate passing; runs timed to meet the pass without losing momentum.', 'about 6-8 per side', 12, 16, 'half pitch', NULL, NULL, NULL, true, false, true, NULL, 610),
  ('Switch wide with full back overlap or underlap', 'combination', 'unopposed', 'in_possession', 296, 297, 'Session (Situation 18): Practice 2', 'Bielsa (Leeds United)', 'Full backs time forward runs after a switch to make a 2v1 wide and get in behind the back line.', 'Half pitch with two goals and keepers; adds attacking midfielders, wingers, forwards and spares, plus 4 mannequins as the opposing back four; runs on both sides.', 'Defensive midfielder hits a long switch to the far winger or the full back. The full back overlaps to receive directly or via the attacking midfielder as a link, gets behind the mannequins and crosses for the forward or attacking midfielder to score.', 'Forward and attacking midfielder pairs rotate; wide starters rotate with full backs.', 'Scenario B: switch always to the winger and the full back underlaps inside the full back mannequin to receive and cut a low cross for the forward.', NULL, 'about 8-10 per side', 16, 22, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Weak side full back switch vs back 4', 'phase_of_play', 'opposed', 'in_possession', 298, 298, 'Session (Situation 18): Practice 3', 'Bielsa (Leeds United)', 'Shift the back four to one side then switch so the weak side full back can receive between the lines or create a 2v1 wide.', 'Half pitch, one goal with keeper; 8 white outfielders (no centre backs) v 4 red defenders and keeper, with mannequins as the red midfield line.', 'Defensive midfielder passes to one full back to pull the reds across, then whites switch play using a trained combination and the far full back runs forward to receive and attack.', 'Two whites per position allowed to keep the tempo high.', NULL, 'Quick accurate passing; well-timed runs; read the defenders to pick the solution.', '8v4+GK', 13, 21, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Weak side switch dynamic 8v8 game', 'conditioned_game', 'opposed', 'in_possession', 299, 299, 'Session (Situation 18): Practice 4', 'Bielsa (Leeds United)', 'Use switches of play and weak side full back runs in a game.', 'Half pitch, one big goal with keeper for whites, two mini goals near halfway for reds.', '8v8 plus keeper; whites build, switch and use full back runs to get between the lines or 2v1 wide; reds win it and counter to the mini goals.', 'White goal 1 point, 3 points if it comes from breaking through with a trained switch of play.', NULL, 'As the previous practice.', '8v8 (+GK)', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 640)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'marcelo-bielsa-attacking-tactics-and-sessions') b;
INSERT INTO schema_migrations (filename) VALUES ('2224-exercises-book-marcelo-bielsa-attacking-tactics-and-sessions.sql') ON CONFLICT DO NOTHING;
